from typing import Annotated, Any, Literal, Union
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

# Mocking Tag and Discriminator since they might be from pydantic or some other library
# In the issue they are used as Annotated[ApplePie, Tag("apple")]
# Pydantic 2.0 introduced Discriminated Unions. 
# Let's check if Tag and Discriminator are available in the environment.

try:
    from pydantic import Tag, Discriminator
except ImportError:
    # If they are not available, we can define them as dummy classes for reproduction
    class Tag:
        def __init__(self, value): self.value = value
    class Discriminator:
        def __init__(self, value): self.value = value

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()
@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert():
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 3})
    print(f"Response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

test_dessert()
